import { useNavigate } from "react-router-dom";

function About(props) {
  const navigate = useNavigate();
  function logoutHandler() {
    navigate(-1);
  }

  return (
    <div>
      <h1>This is a About page</h1>
      <h2> Hello :{}</h2>
      <button onClick={logoutHandler}>Logout</button>
    </div>
  );
}

export default About;
